dr=['主として気温の鉛直勾配を基準とする区分である。','端数の微量成分や水蒸気を除いた粗い概数として適切。','原典は密度と記載。標準モデルで約0.414kg/m³対地表1.225、比約0.338となり1/4とは差がある。圧力比約0.26との混同があり得るが、原典を圧力へ改変しない。','代表的な成層圏界面の加熱はオゾンの紫外吸収。温室気体一般の赤外作用へ置換できない。','乱流混合が分子拡散より強い均質圏の主要長寿命気体を指す。水蒸気・オゾン等まで一様とはしない。']
add('R01-REG-APPLIED-19','大気の層序、組成、密度低下、成層圏加熱と均質圏を比較する。',dv,dr,4,'50km付近の温度極大をCO2の赤外吸収に帰す4が不適切である。オゾンのUV吸収で成層圏を加熱する。ただし3の密度1/4は標準モデル約0.34との精度差を残し、圧力への無断校正をしない。公式4と独立4の一致は全ての概数の厳密保証ではない。','鉛直温度構造と質量密度・混合比を区別する','atmospheric_vertical',['layers','hydrostatic','ozone'],['atm_noaa_layers','atm_us1976','atm_jma_ozone'],ambiguity='肢3の10km密度1/4と標準モデル約0.34に差。原典密度を圧力へ改変しない。概数の許容精度をAstra査読待ち。',verdicts=['適切','適切（概数）','概数精度に疑義','不適切','適切（主要乾燥成分）'])
add('R01-REG-APPLIED-22','季節・緯度収支、太陽放射の主帯域、反射率、太陽定数の定義を比較する。',[rv[2],rv[4],'太陽放射の約半分は可視光線。','入射の約15%が反射散乱され宇宙へ戻る。',rv[3]],[rr[2],rr[4],'太陽光スペクトルの主な一部が可視であるという概数と合う。残りは主に赤外と一部紫外。','全球反射は約3割の代表値であり、15%は小さすぎる。',rr[3]],3,'太陽放射の波長分布は可視・近赤外が中心である。3の約半分可視が適切。他肢の距離を季節原因とする説明、緯度収支の逆転、15%反射、大気下端定義を分けて否定する。','放射の波長帯・反射率・幾何の区別','earth_radiation_budget',['radiation','geometry'],['atm_nasa_budget','atm_nasa_transport'],direction='最も適切。')
add('R01-RET-APPLIED-20','指定された全球平均入射342W/m²に対し、反射散乱で宇宙へ戻る放射束を選ぶ。',['68W/m²','107W/m²','137W/m²','171W/m²','205W/m²'],['入射の約20%で代表約31%より小さい。','107/342=約0.313で約31%の全球反射と合う。','約40%で問題の全球代表反射率より大きい。','約50%で問題の全球代表反射率より大きい。','約60%で反射を過大評価している。'],2,'問題の採る全球平均値では反射率'+m(r'\alpha\simeq0.31')+'なので'+m(r'F_{\rm refl}=\alpha F_{\rm in}\simeq0.31\times342\simeq106\ {\rm W/m^2}')+'。最近の107を選ぶ。342は球面平均であり、ここで再び4で割らない。NASAの代表収支図にも342/107があるが、現在のすべての年の厳密な観測値とはしない。','全球アルベドと球面平均放射束','earth_radiation_budget',['radiation','geometry'],['atm_nasa_budget','atm_nasa_albedo'],conditions={'方向':'最も適切。','指定':'大気上端の平均342W/m²。宇宙へ戻る反射散乱の和。'},calc=True,direction='最も適切。')
lv=['対流圏質量は気圏の約3/4。','対流圏の気温減率は3℃/km。','対流圏界面は低緯度で高く高緯度で低い。','成層圏では高度とともに気温上昇。','オゾンの約9割は成層圏。']
lr=['大気質量が下層へ集中する代表的な全球概数。界面の緯度・季節差で厳密値は変わる。','標準的な対流圏環境減率は約6.5K/km。乾燥断熱9.8K/kmや湿潤断熱・実際の逆転層と区別する。','低緯度の高い温度と深い対流により界面は高くなる。','オゾン吸収による加熱が上方の温度増加を作る。成層圏の下部がほぼ等温の場合を無視した厳密な全高度単調則ではない。','全球オゾン鉛直分布の代表値。地表オゾン汚染の存在を否定しない。']
for q,order,ans in [('R01-RET-APPLIED-21',[0,1,2,3,4],2),('R04-REG-APPLIED-22',[1,4,3,2,0],1)]:
 add(q,'対流圏の質量・気温減率・界面高度と成層圏温度、オゾンの分布を判定する。',[lv[i] for i in order],[lr[i] for i in order],ans,'環境減率の標準値は約6.5K/kmであり、3K/kmという肢が不適切。温度の観測平均と、気塊の断熱移動を表す9.8K/km等を混ぜない。界面は赤道側で高く、オゾンが多い成層圏ではUV加熱による温度上昇が生じる。','大気の鉛直構造と環境・断熱気温減率','atmospheric_vertical',['layers','lapse','ozone'],['atm_noaa_layers','atm_us1976','atm_jma_ozone'])
add('R02-REG-APPLIED-21','大循環、成層圏加熱、上層組成、海陸風と地衡風の記述を比較する。',['低緯度ハドレー、中緯度フェレル、高緯度極循環。','成層圏オゾンUV吸収で約50km温度極大。','80kmまでほぼ一定、170km超でO原子、1000km付近でHe主要。','夜間は地表で海から陸へ海風。','傾度力と転向力の釣合いで等圧線沿いの地衡風。'],['緯度帯に対応する帯状平均循環の基本模式である。瞬時の風を3つの閉じた固定セルだけで表さない。','層序とオゾンの放射作用が整合する。','均質圏から上方の解離と拡散分離の定性的説明は合う。優勢成分が切り替わる高度は太陽活動等に依存し、この2数値の一次数表検証は未完了。','夜間は陸が速く冷え、基本の地表循環は陸→海の陸風。','摩擦・加速度が小さく赤道から離れた条件での理論風である。'],4,'日中の陸加熱と夜間の陸冷却を分けると夜間海→陸の4が不適切となる。大循環は緯度帯、地衡風は運動方程式の近似で判定する。3の原子O・Heの数値高度は定性的な分離の理解とは別に一次数表を要するため、全肢確認へ昇格させない。','鉛直組成と循環モデルの適用条件','atmospheric_circulation',['composition','wind','local'],['atm_noaa_winds','atm_noaa_layers','atm_us1976'],ambiguity='肢3の170km超O・1000km付近He主要の数値高度は一次数表未確認。原典の数字は保持し部分校正。',verdicts=['適切（平均模式）','適切','数値高度は要確認','不適切','適切（近似条件）'])
add('R02-REG-APPLIED-22','蒸発潜熱のエネルギー割合、温室効果、海陸輸送、淡水更新と日本の水収支を比較する。',['入射太陽エネルギーの約1割が蒸発潜熱になる。','水蒸気は赤外吸収で温暖な気候へ寄与。','陸の降水超過は海洋からの水蒸気輸送による。','淡水資源が枯渇しないのは大気滞留が短く豊富な降水があるため。','日本は流出が大きく蒸発散が小さい。'],['代表収支の78/342≈0.23で約1/4、約1割ではない。地表正味日射を分母にすればさらに比が変わる。','水蒸気は自然温室効果を支える。人為起源の追加強制力と同一のランキングへしない。','長期の海陸区分の全球平均収支と整合する。地域や時期の全てで降水超過を保証しない。','全球的に水が再生されることは説明できるが、地域の渇水・地下水過剰取水等の枯渇がないという普遍的保証にはならない。','日本の多雨と流出優勢という代表的説明。年・流域による変動があり、原典の比較分母や対象期間は未指定である。'],1,'NASA代表収支の潜熱78W/m²と入射342W/m²の比は約23%である。入射の約1割とする1が不適切で独立解答・公式とも1。ただし4の淡水が枯渇しないという表現は、全球循環の更新と地域資源の不足を区別する必要がある。5も全球又は他国との比較範囲が明示されないので、定量的に全国一律の低蒸発散とは教えない。','水の再生流量と熱収支の分母','water_budget_residence',['water','radiation','transport'],['atm_nasa_budget','atm_usgs_cycle'],ambiguity='公式1を保持。肢4は全球更新と地域枯渇を区別する適用範囲疑義、肢5は日本の流出/蒸発散の比較分母・期間が未指定で定量的な一次統計未確認。',calc=True,verdicts=['不適切','適切','適切（全球長期）','適用範囲に疑義','定性傾向・定量範囲要確認'])
add('R05-REG-APPLIED-20','降水pHの地域差、対数比、炭酸平衡、中和と酸性沈着の影響を判定する。',['海洋上・極域の降水はpH8以上が多い。','pH5はpH6の10倍のH+。','大気CO2と平衡する水は約pH5.6。','乾燥地でNH3等中和によりpH7近くなる場合が多い。','酸性雨は森林・魚類・歴史建造物へ被害を起こす。'],['海水の弱アルカリ性を降水へ移せない。雨のpHはCO2と酸性/中和成分で決まり、場所名だけで一般に8以上としない。','10^-5/10^-6=10。対数尺度の比較である。','25℃付近の希薄水の代表的目安。CO2分圧や温度、他の溶質が変われば同じ値ではない。','アンモニア・土壌由来アルカリ成分は酸を中和する。全乾燥地で必ず7の保証ではない。','酸性沈着による水・土壌の変化と鉱物・金属への作用が生態系と構造物へ影響する。'],1,'海に接している雨と海水は別の相であり、海水のpHをそのまま降水へ代入できない。CO2平衡・硫酸硝酸・塩基性土壌成分等の収支で判断するため1が不適切。pH5.6を人為汚染がない全降水の固定値にもせず、中和と自然酸性源を考える。','降水の酸塩基平衡と酸性沈着の対象','precipitation_chemistry',['acid'],['atm_jma_acid','atm_jma_acid2014'])
add('R07-REG-APPLIED-21','大気密度の概数、界面の緯度差、主要成分の混合、オゾン分布と層序を比較する。',[dv[2],'対流圏界面は赤道より極域で高い。','N2/O2/Arの組成は数10kmまでほぼ一定。','全オゾンの約10%が対流圏。',dv[0]],[dr[2],'低緯度では深い対流と高温により界面は高い。逆にしたこの肢が明白な誤り。','均質圏の主要長寿命成分の混合比の概数。微量気体や水蒸気の分布は同じではない。','約90%成層圏という代表分布の補集合であり整合する。',dr[0]],2,'低緯度の対流圏界面は高く、極域は低いので2が不適切。ただし1は標準モデルの10km密度比約0.34と1/4の精度差があり、原典の密度を圧力へ書き換えず部分校正に残す。公式正答2と別肢の概数精度の査読を分ける。','温度層序・密度と緯度変化','atmospheric_vertical',['layers','hydrostatic','ozone'],['atm_noaa_layers','atm_us1976','atm_jma_ozone'],ambiguity='肢1の10km密度1/4は標準モデル約0.34と差があり概数精度を査読待ち。原典の数値・密度という語は保持。',verdicts=['概数精度に疑義','不適切','適切（主要成分）','適切（概数）','適切'])
